/* ============ ROTEIRO: regras de roteiro dos vídeos de referência + elementos e telas novos no estilo Cinemático ============ */

/* ---------- script rules (go into every generation prompt) ---------- */
const ROTEIRO_GUIDE = `QUALIDADE DO ROTEIRO (técnicas de canais que viralizam com histórias narradas):
GANCHO — a 1ª frase já apresenta a regra/conflito inteiro, em até 3s. Fórmulas que funcionam:
 • Regra mágica: "Nesta cidade, [regra fora do comum]." / "Num mundo onde [regra]..." e logo em seguida o preço da regra ("mas você só volta uma vez. E nunca mais.").
 • E se: "E se [evento extremo] e nunca mais parasse?" e avança em etapas de tempo (HORA 1, DIA 10, 1 MÊS, 1 ANO) com dados reais.
 • Salto no tempo: "Uma escola recebe uma foto que mostra cada aluno 25 anos depois." e revela um por um, com reviravolta no que parecia pior/melhor.
 • Herói invisível: "O seu Valdir dirige o ônibus 47 há 40 anos e quase ninguém sabe o nome dele."
 • Mistério afetivo: "O Vitinho tinha um melhor amigo que ele nunca tinha visto."
CORPO — frases curtas (3 a 8 palavras), uma imagem por frase; detalhes concretos e números específicos (6 da manhã, 86 anos, 47 há 40 anos, 182.500 vezes); nomes brasileiros e carinhosos (Vitinho, seu Valdir, dona Dalva); exemplos rápidos de como a regra afeta pessoas diferentes (o padeiro, a professora, o prefeito); um refrão que volta (ex.: "E nunca mais."); narrador pode ser criança em 1ª pessoa ("A minha diz: esquisito.").
VIRADA — a partir de ~70% do vídeo, revele quem é/por que (o amigo era um senhor de 86 anos; o menino que todos achavam fraco virou o herói). Emoção > informação.
FINAL — 1 frase de lição curta e verdadeira, sem sermão, e de preferência fecha em loop com a imagem do início; ou pergunta para comentar; em série, "parte 2". Nunca termine em resumo morno.
Ritmo: troca de cena a cada 1,5–3s; palavra-chave da fala marcada com *asteriscos*.`;

const ROTEIRO_ELEMENTS = `Elementos e telas extras (use quando a história pedir):
things: polaroid (foto "label":"25 ANOS DEPOIS"), corkboard (quadro de investigação com barbante vermelho), chalkboard ("label":"2 + 2 = ?"), counter (bolha de número sobre a cabeça; "value":"31", anim "bounce" = +1), portal (buraco de luz no chão), magnifier (lupa com ?), alarm (despertador; anim "shake" toca), brickwall (muro alto com ? do outro lado; "label":"3 m"), jar (pote com algo dentro; "label"), busfront (ônibus de frente; "label":"47").
obj (cena tipo "obj", item.type): eye {label:"?"} (close extremo de um olho com algo refletido), tubes {a,av,b,bv,sub:"mm"} (tubos de comparação enchendo), stage {label:"HORA 1",sub:"chovendo sem parar"} (cartela de etapa de tempo), cards {text:"OBRIGADO / POR / ESPERAR / A GENTE"} (pessoas segurando cartolinas, uma palavra por cartão), brmap {text:"São Paulo; Rio de Janeiro", sub:"título"} (mapa do Brasil com pinos), follow {name:"@seucanal", label:"Novo vídeo todo dia"} (botão Seguir no final).
fx extra: "fx":{"counter":{"label":"CHOVENDO HÁ","value":"10 DIAS"}} (contador fixo no canto, ótimo em "E se").`;

const _climaBrief2 = climaBrief;
climaBrief = function (c) { return _climaBrief2(c) + '\n' + ROTEIRO_GUIDE + '\n' + ROTEIRO_ELEMENTS + '\n'; };

/* ---------- fx: running counter in the corner ---------- */
const _normFx2 = normFx;
normFx = function (raw) {
  const o = _normFx2(raw) || {}, c = raw?.fx?.counter ?? raw?.p?.counter;
  if (c && (c.value || c.label)) o.counter = { label: String(c.label || '').slice(0, 24), value: String(c.value || '').slice(0, 16) };
  return Object.keys(o).length ? o : null;
};
const _drawSceneFx2 = drawSceneFx;
drawSceneFx = function (ctx, W, H, s, t, d, P) {
  _drawSceneFx2(ctx, W, H, s, t, d, P);
  const c = s.fx?.counter; if (!c) return;
  const m = Math.min(W, H); ctx.save(); ctx.textAlign = 'right'; ctx.textBaseline = 'top';
  ctx.font = `700 ${m * .024}px Inter, sans-serif`; const lw = ctx.measureText(c.label.toUpperCase()).width; ctx.font = `900 ${m * .05}px Poppins, sans-serif`; const vw = ctx.measureText(c.value.toUpperCase()).width;
  const w = Math.max(lw, vw) + m * .05, x = W - m * .035;
  ctx.fillStyle = 'rgba(12,12,14,.72)'; rr(ctx, x - w, m * .035, w, m * .11, m * .015); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,.7)'; ctx.font = `700 ${m * .024}px Inter, sans-serif`; ctx.fillText(c.label.toUpperCase(), x - m * .025, m * .05);
  ctx.fillStyle = '#fff'; ctx.font = `900 ${m * .05}px Poppins, sans-serif`; ctx.fillText(c.value.toUpperCase(), x - m * .025, m * .078); ctx.restore();
};

/* ---------- caption preset "Conto": sentence case, key words yellow ---------- */
CAPTION_PRESETS.conto = { name: 'Conto', desc: 'Frase normal (não maiúscula), palavras-chave em amarelo — estilo histórias narradas' };
function drawContoCaptions(ctx, g, W, H, y, t, m, maxW) {
  const items = g.words.map(w => ({ ...w, hot: /\*/.test(w.text), s: w.text.replace(/\*/g, '') })).filter(it => it.s);
  let size = m * .062; const font = z => `800 ${z}px "Poppins", ${FALLBACK}`; ctx.font = font(size);
  const spc = () => size * .26, width = () => items.reduce((a, it) => a + ctx.measureText(it.s).width, 0) + spc() * (items.length - 1);
  while (width() > maxW && size > m * .03) { size *= .93; ctx.font = font(size); }
  let x = (W - width()) / 2; ctx.textAlign = 'left'; ctx.textBaseline = 'middle'; ctx.lineJoin = 'round';
  for (const it of items) {
    const on = t >= it.t0 - .03, w = ctx.measureText(it.s).width;
    ctx.save(); if (!on) ctx.globalAlpha *= .45;
    ctx.strokeStyle = 'rgba(20,16,14,.85)'; ctx.lineWidth = size * .16; ctx.strokeText(it.s, x, y);
    ctx.fillStyle = it.hot && on ? '#ffd23f' : '#fff'; ctx.fillText(it.s, x, y); ctx.restore(); x += w + spc();
  }
}

