      ctx.fillStyle = 'rgba(220,235,245,.25)'; rr(ctx, x - tw / 2, top, tw, th, tw * .2); ctx.fill(); const h = th * (v / mx) * k; const g = ctx.createLinearGradient(0, top + th - h, 0, top + th); g.addColorStop(0, '#6ab6e0'); g.addColorStop(1, '#2a6fa0'); ctx.save(); rr(ctx, x - tw / 2, top, tw, th, tw * .2); ctx.clip(); ctx.fillStyle = g; ctx.fillRect(x - tw / 2, top + th - h, tw, h); ctx.restore();
