  stage(ctx, K, m, W, H, it, t) { const k = ease.out(clamp(t / .35)); ctx.save(); ctx.scale(lerp(1.4, 1, k), lerp(1.4, 1, k)); ctx.globalAlpha *= k; ctx.shadowColor = 'rgba(0,0,0,.5)'; ctx.shadowBlur = m * .03; K.txt(String(it.label || 'HORA 1').toUpperCase(), 0, 0, m * .16, '#fff', 900, 'center'); ctx.restore(); if (it.sub) K.txt(String(it.sub).toUpperCase(), 0, m * .14, m * .035, 'rgba(255,255,255,.7)', 700, 'center'); },
